SELECT Catastrophe_Name
FROM catastrophe
ORDER BY Catastrophe_Name ASC;

SELECT SUM(pa.Policy_Amount) AS total_premium
FROM policy_amount pa
JOIN premium p ON pa.Policy_Amount_Identifier = p.Policy_Amount_Identifier;

SELECT AVG(Loss_Ratio) AS average_loss_ratio
FROM fire_claim
WHERE Year_Built < 1970;

SELECT COUNT(DISTINCT Postal_Code) AS distinct_zip_codes
FROM location_address
WHERE Postal_Code IS NOT NULL;

SELECT SUM(ca.Claim_Amount) AS total_loss_reserves
FROM claim_amount ca
JOIN loss_reserve lr ON ca.Claim_Amount_Identifier = lr.Claim_Amount_Identifier;
